function validate([number]) {
  if (typeof number !== 'string' || number.length < 2 || number.length > 100) return 'number has 2 to 100 characters.';
  if (!/^[0-9 -]*$/.test(number)) return 'number may contain only digits, spaces and dashes.';
  if (number.replace(/[^0-9]/g, '').length < 2) return 'number needs at least two digits.';
  return null;
}

