function reformatNumber(number) {
  const digits = number.replace(/[^0-9]/g, '');
  const blocks = [];
  let start = 0;
  while (digits.length - start > 4) {
    blocks.push(digits.slice(start, start + 3));
    start += 3;
  }
  const remaining = digits.length - start;
  if (remaining === 4) {
    blocks.push(digits.slice(start, start + 2));
    blocks.push(digits.slice(start + 2));
  } else {
    blocks.push(digits.slice(start));
  }
  return blocks.join('-');
}

