function reformatNumber(number) {
  let digits = '';
  for (const ch of number) if (ch >= '0' && ch <= '9') digits += ch;
  const n = digits.length;
  const sizes = [];
  if (n % 3 === 0) for (let k = 0; k < n / 3; k++) sizes.push(3);
  else if (n % 3 === 2) { for (let k = 0; k < (n - 2) / 3; k++) sizes.push(3); sizes.push(2); }
  else { for (let k = 0; k < (n - 4) / 3; k++) sizes.push(3); sizes.push(2, 2); }
  let out = '', pos = 0;
  for (const size of sizes) {
    if (out) out += '-';
    out += digits.substr(pos, size);
    pos += size;
  }
  return out;
}

