function generate(rand, size) {
  const length = size === 'large' ? 90 + Math.floor(rand() * 11) : 2 + Math.floor(rand() * 13);
  const digitShare = size === 'large' ? 0.3 + rand() * 0.7 : 0.4 + rand() * 0.6;
  for (;;) {
    let number = '';
    for (let i = 0; i < length; i++) {
      if (rand() < digitShare) number += String(Math.floor(rand() * 10));
      else number += rand() < 0.5 ? ' ' : '-';
    }
    if (number.replace(/[^0-9]/g, '').length >= 2) return [number];
  }
}
